 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    largest = (0, None)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if size > largest[0]:
                largest = (size, color)
    return [[largest[1]] * 3 for _ in range(3)]
